import assert from "node:assert/strict";
import { test } from "node:test";

import {
  isUsableAgentSessionId,
  loadTranscript,
  parseTranscript,
  parseTranscriptOutput,
  transcriptCommand,
  TRANSCRIPT_TAIL_BYTES,
  type TranscriptExec,
} from "./terminal-transcript";

/** Fixture ids only — the real ones are generated by the agent, not by us. */
const CLAUDE_ID = "6fd5b5f9-959b-4845-91b8-e2f6cefc1a51";
const CODEX_ID = "01a09538-e6de-7ca3-88e7-dd35d65e84f1";

function jsonl(...records: unknown[]): string {
  return `${records.map((record) => JSON.stringify(record)).join("\n")}\n`;
}

/* ------------------------------------------------------------------ *
 * Claude Code
 * ------------------------------------------------------------------ */

/**
 * Every record here except the two prompts and the one assistant text is a trap observed in a
 * real file: in one sampled tail 85 of 93 `user` records were `tool_result` payloads, 5 carried
 * `isMeta`, and 2 were slash-command bookkeeping.
 */
const CLAUDE_FIXTURE = jsonl(
  { type: "last-prompt", value: "还有略有点卡" },
  { type: "ai-title", title: "x" },
  { type: "file-history-snapshot", files: [] },
  { type: "atis-latch" },
  { type: "system", content: "hook ran" },
  { type: "user", isSidechain: false, message: { role: "user", content: "还有略有点卡, 或者说松手后先隐藏缩略图再操作数据库呢?" } },
  {
    type: "assistant",
    isSidechain: false,
    message: { role: "assistant", content: [{ type: "thinking", thinking: "内部推演，不该进纸面", signature: "…" }] },
  },
  {
    type: "assistant",
    isSidechain: false,
    message: {
      role: "assistant",
      content: [{ type: "text", text: "验过了，两件都成立。\n\n段落之间的换行是作者写的，不是终端折的。" }],
    },
  },
  {
    type: "assistant",
    isSidechain: false,
    message: {
      role: "assistant",
      content: [{ type: "tool_use", id: "toolu_1", name: "Bash", input: { command: "git status", description: "看看改了啥" } }],
    },
  },
  {
    type: "user",
    isSidechain: false,
    message: { role: "user", content: [{ tool_use_id: "toolu_1", type: "tool_result", content: "824:private struct …" }] },
  },
  { type: "user", isMeta: true, message: { role: "user", content: "Caveat: the messages below were generated by …" } },
  { type: "user", isSidechain: false, message: { role: "user", content: "<command-name>/clear</command-name>" } },
  {
    type: "user",
    isSidechain: false,
    message: { role: "user", content: [{ type: "text", text: "[Request interrupted by user]" }] },
  },
  {
    type: "user",
    isSidechain: true,
    message: { role: "user", content: "子 agent 的提问，不该出现在这一页" },
  },
  {
    type: "assistant",
    isSidechain: true,
    message: { role: "assistant", content: [{ type: "text", text: "子 agent 的回答，同样不该出现" }] },
  },
  {
    type: "user",
    isSidechain: false,
    message: { role: "user", content: [{ type: "text", text: "继续吧" }] },
  },
);

test("claude：只留人类提问与 agent 正文，工具调用压成一行地标", () => {
  assert.deepEqual(parseTranscript("claude", CLAUDE_FIXTURE), [
    { kind: "prompt", text: "还有略有点卡, 或者说松手后先隐藏缩略图再操作数据库呢?" },
    { kind: "prose", text: "验过了，两件都成立。\n\n段落之间的换行是作者写的，不是终端折的。" },
    { kind: "tool", label: "Bash(git status)" },
    { kind: "prompt", text: "继续吧" },
  ]);
});

test("claude：tool_result / isMeta / 斜杠命令 / sidechain / 中断标记一条都不进纸面", () => {
  const entries = parseTranscript("claude", CLAUDE_FIXTURE);
  const texts = entries.map((entry) => (entry.kind === "tool" ? entry.label : entry.text)).join("\n");
  for (const forbidden of [
    "824:private struct",
    "Caveat:",
    "<command-name>",
    "[Request interrupted by user]",
    "子 agent",
    "内部推演",
  ]) {
    assert.equal(texts.includes(forbidden), false, `不该出现：${forbidden}`);
  }
});

test("claude：允许名单之外的记录类型一律忽略，不靠猜", () => {
  const unknown = jsonl(
    { type: "cost-state", usd: 1 },
    { type: "continued-in", sessionId: CLAUDE_ID },
    { type: "queue-operation", op: "enqueue" },
    { type: "permission-mode", mode: "bypassPermissions" },
    { type: "attachment", path: "/tmp/x.png" },
  );
  assert.deepEqual(parseTranscript("claude", unknown), []);
});

